    # The exploration's id, permanent and unique; the object id derives from
    # it, so a re-registration of the same exploration revises the same
    # object.
    exploration_id: "str"

    # The mission the exploration was run for (its authored `mission_id`).
    mission_id: Optional["str"]

    # That file's content revision at this write.
    program_cid: Optional["ContentId"]

    # The Drive file object holding the stored program.
    program_id: "ObjectId"

    # sha256 (hex) of the program bytes; the projector verifies it.
    program_sha256: "str"

    # The principal who asked for the exploration (oid).
    requested_by: Optional["str"]

    # A one-line digest of what the run produced, empty until it ran.
    result_digest: Optional["str"]

    # Where the exploration is in its life: what a board filters on.
    status: Optional["str"]

